contracts/MetUserState.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { OApp, Origin } from "@layerzerolabs/oapp-evm/contracts/oapp/OApp.sol";
import { OAppOptionsType3 } from "@layerzerolabs/oapp-evm/contracts/oapp/libs/OAppOptionsType3.sol";
import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title MetUserState
 * @dev Contract for managing user staking state across chains using LayerZero
 */
contract MetUserState is OApp, OAppOptionsType3, ReentrancyGuard {
    // Message types - must match TokenStaking constants
    uint8 public constant STAKE_MSG_TYPE = 1;
    uint8 public constant UNSTAKE_MSG_TYPE = 2;

    // Valid lock durations (must match TokenStaking constants)
    uint256 public constant THREE_MONTHS_DURATION = 3 * 30 days; // 90 days
    uint256 public constant SIX_MONTHS_DURATION = 6 * 30 days; // 180 days

    // Bounds for lock duration validation
    uint256 public constant MIN_LOCK_DURATION = 1 days; // Minimum 1 day
    uint256 public constant MAX_LOCK_DURATION = 2 * 365 days; // Maximum 2 years (730 days)

    event StakeReceived(
        address indexed user,
        uint256 amount,
        uint256 lockDuration,
        uint256 stakeIndex,
        uint256 blockNumber,
        uint32 srcEid
    );
    event UnstakeReceived(address indexed user, uint256 stakeIndex, uint256 blockNumber, uint32 srcEid);
    event MessageProcessed(uint8 messageType, address indexed user, bytes32 guid);
    event InvalidMessageReceived(uint8 messageType, bytes32 guid);
    event StakeRepaired(address indexed user, uint256 stakeIndex, uint256 oldAmount, uint256 newAmount, string reason);

    struct Stake {
        uint256 amount;
        uint256 lockDuration;
        uint256 startTime;
        uint256 blockNumber;
        bool active;
    }

    mapping(address => uint256) public totalStakedGlobal;
    mapping(address => Stake[]) public userStakes;

    // Track message processing to prevent duplicates
    mapping(bytes32 => bool) public processedMessages;

    error MessageAlreadyProcessed();
    error InvalidMessageType();
    error InvalidUser();
    error InsufficientStakedAmount();
    error StakeIndexOutOfBounds();
    error StakeNotActive();
    error ZeroAmount();
    error LockPeriodNotEnded();
    error InvalidLockDuration();
    error InvalidRepairAmount();
    error RepairWouldCauseOverflow();

    /**
     * @dev Constructor initializes the contract with the endpoint and owner
     * @param _endpoint Address of the LayerZero endpoint
     * @param _owner Address of the contract owner
     */
    constructor(address _endpoint, address _owner) OApp(_endpoint, _owner) Ownable(_owner) {}

    /**
     * @dev LayerZero message handler using OApp pattern
     * @param _origin Origin information of the message
     * @param _guid Unique identifier of the message
     * @param payload Encoded message payload
     */
    function _lzReceive(
        Origin calldata _origin,
        bytes32 _guid,
        bytes calldata payload,
        address /*executor*/,
        bytes calldata /*extraData*/
    ) internal override nonReentrant {
        // Prevent duplicate message processing
        if (processedMessages[_guid]) revert MessageAlreadyProcessed();
        processedMessages[_guid] = true;

        // Decode the full payload with all 4 parameters
        (uint8 msgType, address user, uint256 amount, uint256 lockDuration) = abi.decode(
            payload,
            (uint8, address, uint256, uint256)
        );

        // Validate user address
        if (user == address(0)) revert InvalidUser();

        if (msgType == STAKE_MSG_TYPE) {
            _handleStake(user, amount, lockDuration, _origin.srcEid);
        } else if (msgType == UNSTAKE_MSG_TYPE) {
            uint256 stakeIndex = amount;
            _handleUnstake(user, stakeIndex, _origin.srcEid);
        } else {
            emit InvalidMessageReceived(msgType, _guid);
            revert InvalidMessageType();
        }

        emit MessageProcessed(msgType, user, _guid);
    }

    /**
     * @dev Handles a stake payload from TokenStaking
     * @param user Address of the user
     * @param amount Amount of tokens staked
     * @param lockDuration Duration of the lock period
     * @param srcEid Source endpoint ID
     */
    function _handleStake(address user, uint256 amount, uint256 lockDuration, uint32 srcEid) internal {
        // Validate amount
        if (amount == 0) revert ZeroAmount();

        // Validate lock duration bounds: 1 day ≤ lockDuration ≤ 2 years
        // This prevents extremely large durations or zero values from misconfigured or compromised senders
        if (lockDuration < MIN_LOCK_DURATION || lockDuration > MAX_LOCK_DURATION) {
            revert InvalidLockDuration();
        }

        // Validate lock duration matches allowed durations (3 or 6 months only)
        if (lockDuration != THREE_MONTHS_DURATION && lockDuration != SIX_MONTHS_DURATION) {
            revert InvalidLockDuration();
        }

        uint256 stakeIndex = userStakes[user].length;

        // Update global staking state
        totalStakedGlobal[user] += amount;
        userStakes[user].push(
            Stake({
                amount: amount,
                lockDuration: lockDuration,
                startTime: block.timestamp,
                blockNumber: block.number,
                active: true
            })
        );

        emit StakeReceived(user, amount, lockDuration, stakeIndex, block.number, srcEid);
    }

    /**
     * @dev Handles an unstake payload from TokenStaking
     * @param user Address of the user
     * @param stakeIndex Index of the stake to unstake
     * @param srcEid Source endpoint ID
     */
    function _handleUnstake(address user, uint256 stakeIndex, uint32 srcEid) internal {
        // Validate stake index
        if (stakeIndex >= userStakes[user].length) revert StakeIndexOutOfBounds();

        Stake storage stake = userStakes[user][stakeIndex];
        if (!stake.active) revert StakeNotActive();

        if (block.timestamp < stake.startTime + stake.lockDuration) revert LockPeriodNotEnded();

        uint256 amount = stake.amount;

        // Validate amount
        if (amount == 0) revert ZeroAmount();

        // Reduce the total staked amount
        if (totalStakedGlobal[user] < amount) revert InsufficientStakedAmount();
        totalStakedGlobal[user] -= amount;

        // Mark stake as inactive
        stake.active = false;

        emit UnstakeReceived(user, stakeIndex, block.number, srcEid);
    }

    /**
     * @dev Gets all stakes for a user
     * @param user Address of the user
     * @return Array of user's stakes
     */
    function getUserStakes(address user) external view returns (Stake[] memory) {
        return userStakes[user];
    }

    /**
     * @dev Gets the total amount staked by a user
     * @param user Address of the user
     * @return Total staked amount
     */
    function getTotalStakedGlobal(address user) external view returns (uint256) {
        return totalStakedGlobal[user];
    }

    /**
     * @dev ADMIN REPAIR FUNCTION - Use with extreme caution
     * @dev Allows owner to repair corrupted stake state after validation
     * @dev Only use for correcting clear mistakes (e.g., bad LayerZero message)
     * @param user Address of the user whose stake needs repair
     * @param stakeIndex Index of the stake to repair
     * @param correctedAmount Corrected amount for the stake
     * @param reason Reason for the repair (max 256 characters)
     * @notice This function should be used sparingly and only by trusted admins
     * @notice All repairs are permanently logged via events for audit trail
     */
    function repairUserStake(
        address user,
        uint256 stakeIndex,
        uint256 correctedAmount,
        string memory reason
    ) external onlyOwner {
        // Validate inputs
        if (user == address(0)) revert InvalidUser();
        if (stakeIndex >= userStakes[user].length) revert StakeIndexOutOfBounds();
        if (correctedAmount == 0) revert InvalidRepairAmount();

        // Reason should be provided for audit trail (max 256 chars for gas efficiency)
        require(bytes(reason).length > 0 && bytes(reason).length <= 256, "Invalid reason");

        Stake storage stake = userStakes[user][stakeIndex];
        uint256 oldAmount = stake.amount;

        // Calculate the difference
        uint256 difference;
        if (correctedAmount > oldAmount) {
            difference = correctedAmount - oldAmount;
            // Check for overflow when adding to global total
            if (totalStakedGlobal[user] + difference < totalStakedGlobal[user]) revert RepairWouldCauseOverflow();
            totalStakedGlobal[user] += difference;
        } else if (correctedAmount < oldAmount) {
            difference = oldAmount - correctedAmount;
            // Ensure we don't underflow
            if (totalStakedGlobal[user] < difference) revert InsufficientStakedAmount();
            totalStakedGlobal[user] -= difference;
        }
        // If correctedAmount == oldAmount, no change needed (validated as a no-op)

        // Update the stake with corrected amount
        stake.amount = correctedAmount;

        // Emit repair event for audit trail
        emit StakeRepaired(user, stakeIndex, oldAmount, correctedAmount, reason);
    }
}

