// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./PresaleManager.sol";

/**
 * @title TokenClaim
 * @dev Contract for claiming tokens purchased during the presale
 */
contract TokenClaim is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 public constant MAX_DEADLINE_DURATION = 30 days;

    PresaleManager public presaleManager;
    bool public claimsActive;
    bool public emergencyPaused = false;

    mapping(address => uint256) public claimedAmounts;
    // Signature replay protection mapping
    // Security Note: Grows monotonically but bounded by:
    // 1. Each user can only claim once (see claimedAmounts check)
    // 2. Signatures expire after MAX_DEADLINE_DURATION (30 days)
    // 3. Maximum storage growth = number of claims (one per eligible user)
    mapping(bytes => bool) public usedSignatures;

    event TokensClaimed(address indexed claimer, uint256 amount, uint256 stakingRewards);
    event ClaimsStatusUpdated(bool isActive);
    event PresaleManagerUpdated(address newPresaleManager);

    error ZeroAddress();
    error TGENotOccurred();
    error ClaimsNotActive();
    error SignatureAlreadyUsed();
    error AlreadyClaimed();
    error SignatureExpired();
    error DeadlineTooFar();
    error InvalidSignature();
    error NothingToClaim();
    error InsufficientTokenBalance();
    error PresaleNotActive();
    error PresaleEnded();
    error TGEOccurred();

    /**
     * @dev Constructor initializes the contract with the presale manager address
     * @param _presaleManager Address of the presale manager contract
     */
    constructor(address _presaleManager) Ownable(msg.sender) {
        if (_presaleManager == address(0)) revert ZeroAddress();
        presaleManager = PresaleManager(_presaleManager);
        claimsActive = false;
    }

    // ==================== EXTERNAL FUNCTIONS ====================

    /**
     * @dev Toggles the claims status
     * Can only be called by the owner after TGE has occurred
     */
    function toggleClaims() external onlyOwner {
        if (!presaleManager.tgeHasOccurred()) revert TGENotOccurred();
        claimsActive = !claimsActive;
        emit ClaimsStatusUpdated(claimsActive);
    }

    /**
     * @dev Updates the presale manager address
     * @param _presaleManager New presale manager address
     */
    function updatePresaleManager(address _presaleManager) external onlyOwner {
        if (_presaleManager == address(0)) revert ZeroAddress();
        presaleManager = PresaleManager(_presaleManager);
        emit PresaleManagerUpdated(_presaleManager);
    }

    /**
     * @dev Pauses the claims functionality in case of an emergency
     */
    function emergencyPause() external onlyOwner {
        emergencyPaused = true;
    }

    /**
     * @dev Unpauses the claims functionality in case of an emergency
     */
    function emergencyUnpause() external onlyOwner {
        emergencyPaused = false;
    }

    /**
     * @dev Claims tokens based on a signed message
     * @param purchaseAmount Amount of tokens purchased
     * @param stakingReward Additional tokens from staking rewards
     * @param deadline Expiration timestamp for the signature
     * @param signature Cryptographic signature from the trusted signer
     * @notice Signature lifecycles:
     *         - Signatures expire after deadline (MAX_DEADLINE_DURATION = 30 days)
     *         - Each user can only claim once, bounding storage growth
     *         - usedSignatures prevents replay attacks but does not require pruning
     */
    function claimTokens(
        uint256 purchaseAmount,
        uint256 stakingReward,
        uint256 deadline,
        bytes memory signature
    ) external nonReentrant {
        if (emergencyPaused) revert ClaimsNotActive();
        if (!claimsActive) revert ClaimsNotActive();
        _checkPresaleStatus(true); // Require TGE has occurred
        if (usedSignatures[signature]) revert SignatureAlreadyUsed();
        if (claimedAmounts[msg.sender] > 0) revert AlreadyClaimed();
        if (deadline > block.timestamp + MAX_DEADLINE_DURATION) revert DeadlineTooFar();
        if (block.timestamp > deadline) revert SignatureExpired();

        // Mark signature as used to prevent replay attacks
        // Storage growth is bounded: one entry per claim (one per user max)
        usedSignatures[signature] = true;

        bytes32 messageHash = keccak256(
            abi.encodePacked(msg.sender, purchaseAmount, stakingReward, deadline, block.chainid, address(this))
        );
        bytes32 ethSignedMessageHash = MessageHashUtils.toEthSignedMessageHash(messageHash);
        address recoveredSigner = ECDSA.recover(ethSignedMessageHash, signature);

        if (recoveredSigner != presaleManager.trustedSigner()) revert InvalidSignature();

        uint256 totalAmount = purchaseAmount + stakingReward;
        if (totalAmount == 0) revert NothingToClaim();

        claimedAmounts[msg.sender] = totalAmount;

        IERC20 token = IERC20(presaleManager.token());
        if (token.balanceOf(address(this)) < totalAmount) revert InsufficientTokenBalance();

        token.safeTransfer(msg.sender, totalAmount);

        emit TokensClaimed(msg.sender, purchaseAmount, stakingReward);
    }

    /**
     * @dev Gets claim information for a user
     * @param user Address of the user
     * @return claimed Amount already claimed by the user
     * @return canClaim Whether the user can claim tokens
     */
    function getUserClaimInfo(address user) external view returns (uint256 claimed, bool canClaim) {
        (, , , , bool tgeOccurred) = presaleManager.getPresaleStatus();

        bool eligibleToClaim = claimsActive && tgeOccurred && claimedAmounts[user] == 0;

        return (claimedAmounts[user], eligibleToClaim);
    }

    /**
     * @dev Gets the current presale status
     * @return state Current state of the presale
     * @return active Whether the presale is active
     * @return started Whether the presale has started
     * @return ended Whether the presale has ended
     * @return tgeOccurred Whether the TGE has occurred
     */
    function getPresaleStatus()
        external
        view
        returns (PresaleManager.PresaleState state, bool active, bool started, bool ended, bool tgeOccurred)
    {
        return presaleManager.getPresaleStatus();
    }

    /**
     * @dev Allows the owner to recover any ERC20 tokens sent to the contract by mistake
     * @param tokenAddress Address of the token to recover
     * @param amount Amount to recover
     * @param recipient Address to send the tokens to
     */
    function recoverERC20(address tokenAddress, uint256 amount, address recipient) external onlyOwner {
        if (tokenAddress == address(0) || recipient == address(0)) revert ZeroAddress();

        // Don't allow recovering the presale token unless claims are no longer active
        if (tokenAddress == address(presaleManager.token())) {
            require(!claimsActive, "Cannot recover presale tokens while claims are active");
        }

        IERC20(tokenAddress).safeTransfer(recipient, amount);
    }

    // ==================== INTERNAL FUNCTIONS ====================

    /**
     * @dev Checks the presale status
     * @param requireTGE Whether to require TGE to have occurred
     */
    function _checkPresaleStatus(bool requireTGE) internal view {
        (PresaleManager.PresaleState state, bool active, , bool ended, bool tgeOccurred) = presaleManager
            .getPresaleStatus();

        if (requireTGE) {
            if (!tgeOccurred) revert TGENotOccurred();
        } else {
            if (state != PresaleManager.PresaleState.Active) revert PresaleNotActive();
            if (!active) revert PresaleNotActive();
            if (ended) revert PresaleEnded();
            if (tgeOccurred) revert TGEOccurred();
        }
    }
}

contracts/TokenStaking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { OApp, Origin, MessagingFee } from "@layerzerolabs/oapp-evm/contracts/oapp/OApp.sol";
import { OAppOptionsType3 } from "@layerzerolabs/oapp-evm/contracts/oapp/libs/OAppOptionsType3.sol";
import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title TokenStaking
 * @dev Contract for cross-chain token staking using LayerZero
 *
 * @notice This contract is designed as a SENDER-ONLY contract
 * This contract sends staking/unstaking messages to the MetUserState contract via LayerZero
 * and does NOT receive messages itself
 *
 * ARCHITECTURE:
 * - TokenStaking (this contract) sends messages -> MetUserState contract receives
 * - All cross-chain state updates happen on the MetUserState receiver side
 * - Each chain has its own TokenStaking instance that sends to MetUserState
 * - The receiver-side implementation is in MetUserState.sol
 *
 * DEPLOYMENT & MONITORING REQUIREMENTS:
 * 1. MetUserState must be deployed and configured as the receiver before this contract
 * 2. Set proper LayerZero destination endpoint IDs for MetUserState
 * 3. Monitor LayerZero message delivery success/failure on MetUserState side
 * 4. Monitor failed deliveries and implement retry mechanisms in backend
 * 5. Monitor gas costs and LayerZero fee changes across chains
 * 6. Ensure MetUserState has proper access controls for receiving messages
 */
contract TokenStaking is OApp, OAppOptionsType3, ReentrancyGuard {
    using ECDSA for bytes32;

    string public chainId;
    address public trustedSigner;

    // Emergency pause state
    bool public paused;

    // Track used signatures to prevent replay attacks
    mapping(bytes32 => bool) public usedSignatures;

    // Per-user nonce to prevent replay attacks across signatures
    mapping(address => uint256) public nonces;

    // Valid staking durations
    uint256 private constant THREE_MONTHS = 3;
    uint256 private constant SIX_MONTHS = 6;

    // Maximum deadline duration for signatures (30 days)
    uint256 public constant MAX_DEADLINE_DURATION = 30 days;

    // Message types
    uint8 private constant STAKE_MESSAGE = 1;
    uint8 private constant UNSTAKE_MESSAGE = 2;

    event Staked(address indexed user, uint256 amount, uint256 durationMonths, string chainId);
    event Unstaked(uint256 indexed stakeIndex, address indexed user, string chainId);
    event TrustedSignerUpdated(address indexed previousSigner, address indexed newSigner);
    event Paused(address indexed account);
    event Unpaused(address indexed account);
    event NonceUsed(address indexed user, uint256 nonce);

    error InvalidDuration();
    error ZeroAmount();
    error InsufficientFee();
    error ReceivingNotSupported();
    error InvalidSignature();
    error SignatureAlreadyUsed();
    error DeadlineTooFar();
    error SignatureExpired();
    error ContractPaused();

    /**
     * @dev Constructor initializes the contract with the endpoint, owner, and chain ID
     * @param _endpoint Address of the LayerZero endpoint
     * @param _owner Address of the contract owner
     * @param _chainId Chain ID as a string
     * @param _trustedSigner Address of the trusted signer for verifying backend signatures
     */
    constructor(
        address _endpoint,
        address _owner,
        string memory _chainId,
        address _trustedSigner
    ) OApp(_endpoint, _owner) Ownable(_owner) {
        chainId = _chainId;
        trustedSigner = _trustedSigner;
        paused = false;
    }

    // ============ EXTERNAL FUNCTIONS ============

    /**
     * @dev Updates the trusted signer address
     * @param _newSigner New trusted signer address
     */
    function setTrustedSigner(address _newSigner) external onlyOwner {
        address oldSigner = trustedSigner;
        trustedSigner = _newSigner;
        emit TrustedSignerUpdated(oldSigner, _newSigner);
    }

    /**
     * @dev Pauses staking and unstaking operations in case of emergency
     */
    function pause() external onlyOwner {
        if (!paused) {
            paused = true;
            emit Paused(msg.sender);
        }
    }

    /**
     * @dev Unpauses staking and unstaking operations
     */
    function unpause() external onlyOwner {
        if (paused) {
            paused = false;
            emit Unpaused(msg.sender);
        }
    }

    /**
     * @dev Quotes the fee for staking tokens
     * @param dstEid Destination endpoint ID
     * @param amount Amount of tokens to stake
     * @param lockDuration Duration of the stake in months
     * @param options LayerZero options
     * @return fee Messaging fee
     */
    function quoteStake(
        uint32 dstEid,
        uint256 amount,
        uint256 lockDuration,
        bytes calldata options
    ) external view returns (MessagingFee memory fee) {
        bytes memory payload = abi.encode(STAKE_MESSAGE, msg.sender, amount, lockDuration);
        bytes memory combinedOptions = combineOptions(dstEid, STAKE_MESSAGE, options);
        return _quote(dstEid, payload, combinedOptions, false);
    }

    /**
     * @dev Quotes the fee for unstaking tokens
     * @param dstEid Destination endpoint ID
     * @param stakeIndex Index of the stake to unstake
     * @param options LayerZero options
     * @return fee Messaging fee
     */
    function quoteUnstake(
        uint32 dstEid,
        uint256 stakeIndex,
        bytes calldata options
    ) external view returns (MessagingFee memory fee) {
        bytes memory payload = abi.encode(UNSTAKE_MESSAGE, msg.sender, stakeIndex, stakeIndex);
        bytes memory combinedOptions = combineOptions(dstEid, UNSTAKE_MESSAGE, options);
        return _quote(dstEid, payload, combinedOptions, false);
    }

    /**
     * @dev Stakes tokens for a specified duration
     * @param amount Amount of tokens to stake
     * @param durationMonths Duration of the stake in months (3 or 6)
     * @param options LayerZero options
     * @param dstEid Destination endpoint ID
     * @param nonce Unique nonce to prevent replay attacks
     * @param deadline Signature deadline
     * @param signature Signature from the trusted backend
     */
    function stake(
        uint256 amount,
        uint256 durationMonths,
        bytes calldata options,
        uint32 dstEid,
        uint256 nonce,
        uint256 deadline,
        bytes calldata signature
    ) external payable nonReentrant {
        if (paused) revert ContractPaused();
        if (amount == 0) revert ZeroAmount();
        if (durationMonths != THREE_MONTHS && durationMonths != SIX_MONTHS) revert InvalidDuration();

        // Validate deadline is not too far in future
        if (deadline > block.timestamp + MAX_DEADLINE_DURATION) {
            revert DeadlineTooFar();
        }
        if (block.timestamp > deadline) revert SignatureExpired();

        // Enforce per-user nonce
        if (nonce != nonces[msg.sender]) revert InvalidSignature();

        // Check if signature has already been used
        bytes32 sigHash = keccak256(signature);
        if (usedSignatures[sigHash]) revert SignatureAlreadyUsed();
        usedSignatures[sigHash] = true;

        // Verify the signature from the backend
        _verifyStakeSignature(msg.sender, amount, durationMonths, nonce, deadline, signature);

        // Increment nonce after successful verification
        unchecked {
            nonces[msg.sender]++;
        }
        emit NonceUsed(msg.sender, nonce);

        // Calculate lock duration in seconds (using days for demonstration)
        uint256 lockDuration = durationMonths * 30 days;

        bytes memory payload = abi.encode(STAKE_MESSAGE, msg.sender, amount, lockDuration);
        bytes memory combinedOptions = combineOptions(dstEid, STAKE_MESSAGE, options);

        // Quote the required native fee and validate payment
        MessagingFee memory fee = _quote(dstEid, payload, combinedOptions, false);
        if (msg.value < fee.nativeFee) revert InsufficientFee();

        // Pay only the required fee to LayerZero
        _lzSend(dstEid, payload, combinedOptions, MessagingFee(fee.nativeFee, 0), payable(msg.sender));

        // Refund any excess back to the user
        uint256 refund = msg.value - fee.nativeFee;
        if (refund > 0) {
            (bool success, ) = payable(msg.sender).call{ value: refund }("");
            require(success, "Refund failed");
        }

        emit Staked(msg.sender, amount, durationMonths, chainId);
    }

    /**
     * @dev Unstakes tokens
     * @param stakeIndex Index of the stake to unstake
     * @param options LayerZero options
     * @param dstEid Destination endpoint ID
     * @param nonce Unique nonce to prevent replay attacks
     * @param deadline Signature deadline
     * @param signature Signature from the trusted backend
     */
    function unstake(
        uint256 stakeIndex,
        bytes calldata options,
        uint32 dstEid,
        uint256 nonce,
        uint256 deadline,
        bytes calldata signature
    ) external payable nonReentrant {
        if (paused) revert ContractPaused();

        // Validate deadline is not too far in future
        if (deadline > block.timestamp + MAX_DEADLINE_DURATION) {
            revert DeadlineTooFar();
        }
        if (block.timestamp > deadline) revert SignatureExpired();

        // Enforce per-user nonce
        if (nonce != nonces[msg.sender]) revert InvalidSignature();

        // Check if signature has already been used
        bytes32 sigHash = keccak256(signature);
        if (usedSignatures[sigHash]) revert SignatureAlreadyUsed();
        usedSignatures[sigHash] = true;

        // Verify the signature from the backend
        _verifyUnstakeSignature(msg.sender, stakeIndex, nonce, deadline, signature);

        // Increment nonce after successful verification
        unchecked {
            nonces[msg.sender]++;
        }
        emit NonceUsed(msg.sender, nonce);

        bytes memory payload = abi.encode(UNSTAKE_MESSAGE, msg.sender, stakeIndex, stakeIndex);
        bytes memory combinedOptions = combineOptions(dstEid, UNSTAKE_MESSAGE, options);

        // Quote the required native fee and validate payment
        MessagingFee memory fee = _quote(dstEid, payload, combinedOptions, false);
        if (msg.value < fee.nativeFee) revert InsufficientFee();

        // Pay only the required fee to LayerZero
        _lzSend(dstEid, payload, combinedOptions, MessagingFee(fee.nativeFee, 0), payable(msg.sender));

        // Refund any excess back to the user
        uint256 refund = msg.value - fee.nativeFee;
        if (refund > 0) {
            (bool success, ) = payable(msg.sender).call{ value: refund }("");
            require(success, "Refund failed");
        }

        emit Unstaked(stakeIndex, msg.sender, chainId);
    }

    // ============ INTERNAL FUNCTIONS ============

    /**
     * @dev Verifies that the signature is valid for the given parameters
     * @param user Address of the user
     * @param amount Amount of tokens
     * @param durationMonths Duration in months
     * @param nonce Unique nonce to prevent replay attacks
     * @param deadline Signature deadline
     * @param signature Signature from the trusted backend
     */
    function _verifyStakeSignature(
        address user,
        uint256 amount,
        uint256 durationMonths,
        uint256 nonce,
        uint256 deadline,
        bytes memory signature
    ) internal view {
        bytes32 messageHash = keccak256(
            abi.encodePacked(
                "\x19Ethereum Signed Message:\n32",
                keccak256(abi.encodePacked(user, amount, durationMonths, nonce, deadline, block.chainid, address(this)))
            )
        );

        address recoveredSigner = messageHash.recover(signature);
        if (recoveredSigner != trustedSigner) {
            revert InvalidSignature();
        }
    }

    /**
     * @dev Verifies that the signature is valid for unstaking
     * @param user Address of the user
     * @param stakeIndex Index of the stake
     * @param nonce Unique nonce to prevent replay attacks
     * @param deadline Signature deadline
     * @param signature Signature from the trusted backend
     */
    function _verifyUnstakeSignature(
        address user,
        uint256 stakeIndex,
        uint256 nonce,
        uint256 deadline,
        bytes memory signature
    ) internal view {
        bytes32 messageHash = keccak256(
            abi.encodePacked(
                "\x19Ethereum Signed Message:\n32",
                keccak256(abi.encodePacked(user, stakeIndex, nonce, deadline, block.chainid, address(this)))
            )
        );

        address recoveredSigner = messageHash.recover(signature);
        if (recoveredSigner != trustedSigner) {
            revert InvalidSignature();
        }
    }

    /**
     * @dev Required implementation for OApp
     * @notice This function always reverts because this contract is sender-only
     * This design choice ensures TokenStaking acts as a unidirectional sender
     * All incoming messages are invalid and explicitly rejected
     *
     * RECEIVER CONTRACT: MetUserState handles all cross-chain message reception
     * Any attempt to send messages TO this contract indicates a misconfiguration
     */
    function _lzReceive(Origin calldata, bytes32, bytes calldata, address, bytes calldata) internal pure override {
        // Explicitly reject all incoming messages - this is a sender-only contract
        // See contract-level documentation for architecture details
        revert ReceivingNotSupported();
    }
}
